package io.livecut.clips;

import static org.junit.jupiter.api.Assertions.*;
import static io.livecut.clips.ClipPlanValidator.JSON;
import java.util.*;
import org.junit.jupiter.api.Test;
import io.livecut.jobs.JobException;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

class AnswerClipSourceTests {
    private static final String JOB="11111111-1111-4111-8111-111111111111",VIDEO="22222222-2222-4222-8222-222222222222",TURN="33333333-3333-4333-8333-333333333333",SESSION="44444444-4444-4444-8444-444444444444";
    static JsonNode utterances(){var rows=JSON.createArrayNode();for(int i=1;i<=8;i++)rows.addObject().put("utterance_id","u"+i).put("start_ms",(i-1)*1000).put("end_ms",i*1000).put("text","完整原句"+i).put("source_chunk_id","c0");return rows;}
    static JsonNode answer(JsonNode rows){var value=JSON.createObjectNode().put("schema_version","1.0").put("turn_id",TURN).put("session_id",SESSION).put("job_id",JOB).put("video_id",VIDEO).put("source_hash","a".repeat(64)).put("transcript_hash","b".repeat(64)).put("question","解释这些原因").put("answer","这些是视频中的原因。").put("answer_scope","VIDEO");var citations=value.putArray("citations");for(JsonNode row:rows){var citation=citations.addObject();for(String key:List.of("utterance_id","start_ms","end_ms","text"))citation.set(key,row.path(key));}var tool=value.putArray("tool_calls").addObject().put("step",1).put("tool_name","read_context");tool.putObject("arguments").put("utterance_id","u4").put("before",3).put("after",3);var observed=tool.putArray("result_utterance_ids");rows.forEach(row->observed.add(row.path("utterance_id")));value.putObject("provenance").put("text_model_id","qwen-plus").put("prompt_version","video-agent-v1").put("retrieval_mode","none");value.putNull("suggested_clip_instruction");return value;}
    static Map<String,Object> owner(String...selected){JsonNode rows=utterances(),answer=answer(rows);JsonNode source=AnswerClipSource.project(answer,rows,8000,JSON.valueToTree(List.of(selected)));Map<String,Object> result=new HashMap<>();result.put("id","55555555-5555-4555-8555-555555555555");result.put("job_id",JOB);result.put("video_id",VIDEO);result.put("source_hash","a".repeat(64));result.put("transcript_hash","b".repeat(64));result.put("duration_ms",8000L);result.put("instruction","保留这些句的解释");result.put("text_model_id","qwen-plus");result.put("source_json",ClipRequestService.canonicalJson(JSON.valueToTree(Map.of("utterances",rows,"answer_result",answer))));result.put("source_answer_json",ClipRequestService.canonicalJson(source));result.put("source_answer_hash",ClipRequestService.sha(String.valueOf(result.get("source_answer_json"))));return result;}
    static ObjectNode plan(Map<String,Object> owner,String state){var value=JSON.createObjectNode().put("schema_version","1.0");for(String field:List.of("job_id","video_id","source_hash","transcript_hash","instruction"))value.put(field,String.valueOf(owner.get(field)));value.put("request_id",String.valueOf(owner.get("id"))).put("duration_ms",8000);value.putArray("goals").addObject().put("goal_id","answer-source").put("description",String.valueOf(owner.get("instruction")));value.putObject("constraints").put("keep_explanation_complete",true).putArray("exclude");var output=value.putArray("outputs").addObject().put("output_id","anchored-output").put("goal_id","answer-source").put("title","视频原句解释").put("status",state).put("reason","合成证据测试").put("enabled",false);output.putArray("parts");output.putArray("excluded");output.putArray("evidence_utterance_ids");if(!state.equals("NOT_FOUND"))parts(output,"u4","u4");var source=AnswerClipSource.stored(owner).source();value.putObject("provenance").put("text_model_id","qwen-plus").put("prompt_version",AnswerClipSource.PROMPT).put("retrieval_mode","anchor_context").put("index_hash",AnswerClipSource.indexHash(owner,source));return value;}
    static void parts(ObjectNode output,String first,String last){int start=Integer.parseInt(first.substring(1)),end=Integer.parseInt(last.substring(1));output.putArray("parts").addObject().put("start_utterance_id",first).put("end_utterance_id",last).put("start_ms",(start-1)*1000).put("end_ms",end*1000);output.putArray("evidence_utterance_ids").add(first);}
    static String failure(Runnable action){return assertThrows(JobException.class,action::run).getCode();}
    @Test void selectorContainsOnlyUuidAndUniqueIds(){assertNull(AnswerClipSource.selector(null));assertNull(AnswerClipSource.selector(JSON.nullNode()));assertEquals("INVALID_ANSWER_SOURCE",failure(()->AnswerClipSource.selector(JSON.valueToTree(Map.of("turn_id",TURN,"utterance_ids",List.of("u4"),"start_ms",1)))));assertEquals("INVALID_ANSWER_SOURCE",failure(()->AnswerClipSource.selector(JSON.valueToTree(Map.of("turn_id",TURN,"utterance_ids",List.of("u4","u4"))))));assertEquals("INVALID_ANSWER_SOURCE",failure(()->AnswerClipSource.selector(JSON.valueToTree(Map.of("turn_id","bad","utterance_ids",List.of("u4"))))));}
    @Test void projectionIncludesExactCitationAndDeterministicWholeNeighbors(){var source=AnswerClipSource.stored(owner("u4")).source();assertEquals(JSON.valueToTree(List.of("u3","u4","u5")),source.path("context_utterance_ids"));assertEquals(utterances().get(3).path("text"),source.path("citations").get(0).path("text"));assertEquals("INVALID_ANSWER_SOURCE",failure(()->owner("u6","u4")));assertEquals("INVALID_ANSWER_SOURCE",failure(()->owner("unknown")));}
    @Test void longNeighborsAreNotTruncatedAndUtf16AnchorsAreBounded(){JsonNode rows=utterances();((ObjectNode)rows.get(2)).put("text","x".repeat(12001));JsonNode source=AnswerClipSource.project(answer(rows),rows,8000,JSON.valueToTree(List.of("u4")));assertEquals(JSON.valueToTree(List.of("u4","u5")),source.path("context_utterance_ids"));((ObjectNode)rows.get(3)).put("text","😀".repeat(6001));assertEquals("INVALID_ANSWER_SOURCE",failure(()->AnswerClipSource.project(answer(rows),rows,8000,JSON.valueToTree(List.of("u4")))));}
    @Test void frozenAnswerHashSourceAndPrivateResultCannotBeTampered(){var damaged=owner("u4");damaged.put("source_answer_hash","0".repeat(64));assertEquals("ANSWER_SOURCE_INVALID",failure(()->AnswerClipSource.stored(damaged)));var foreign=owner("u4");foreign.put("job_id",UUID.randomUUID().toString());assertEquals("ANSWER_SOURCE_INVALID",failure(()->AnswerClipSource.stored(foreign)));var changed=owner("u4");changed.put("source_json",String.valueOf(changed.get("source_json")).replace("这些是视频中的原因","被篡改答复"));assertEquals("ANSWER_SOURCE_INVALID",failure(()->AnswerClipSource.stored(changed)));}
    @Test void foundCandidatesRequireEveryAnchorAndHonestIndex(){var owner=owner("u4","u6");var candidate=plan(owner,"FOUND");assertEquals("INVALID_CLIP_PLAN",failure(()->ClipPlanValidator.validate(candidate,owner,true)));parts((ObjectNode)candidate.path("outputs").get(0),"u4","u6");assertDoesNotThrow(()->ClipPlanValidator.validate(candidate,owner,true));((ObjectNode)candidate.path("provenance")).put("index_hash","0".repeat(64));assertEquals("INVALID_CLIP_PLAN",failure(()->ClipPlanValidator.validate(candidate,owner,true)));}
    @Test void autoContextCannotBridgeUnobservedSourceButHumanCanExtend(){var owner=owner("u4");var automatic=plan(owner,"FOUND");var expanded=(ObjectNode)automatic.deepCopy();parts((ObjectNode)expanded.path("outputs").get(0),"u1","u8");assertEquals("INVALID_CLIP_PLAN",failure(()->ClipPlanValidator.validate(expanded,owner,true)));assertDoesNotThrow(()->ClipPlanValidator.validateReview(expanded,owner,automatic));var cut=(ObjectNode)automatic.deepCopy();parts((ObjectNode)cut.path("outputs").get(0),"u3","u3");assertEquals("INVALID_CLIP_PLAN",failure(()->ClipPlanValidator.validateReview(cut,owner,automatic)));}
    @Test void missingAndReviewCandidatesNeverGainFoundPermission(){var owner=owner("u4");var missing=plan(owner,"NOT_FOUND");assertDoesNotThrow(()->ClipPlanValidator.validate(missing,owner,true));var review=plan(owner,"NEEDS_REVIEW");var edited=(ObjectNode)review.deepCopy();((ObjectNode)edited.path("outputs").get(0)).put("status","FOUND").put("enabled",true);assertEquals("INVALID_CLIP_PLAN",failure(()->ClipPlanValidator.validateReview(edited,owner,review)));var enabled=(ObjectNode)review.deepCopy();((ObjectNode)enabled.path("outputs").get(0)).put("enabled",true);assertEquals("INVALID_CLIP_PLAN",failure(()->ClipPlanValidator.validateReview(enabled,owner,review)));}
}
